import pandas as pd

def clean(df):
    df = df.copy()
    if df['body_mass_g'].dtype == 'object':
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    return df

def answer(df):
    result = df.groupby('species')['body_mass_g'].sum().to_dict()
    return result
